// Generates src/tokens/generated/{tokens.css,tokens.json} from src/tokens/tokens.ts (ADR 0005).
// Usage: tsx scripts/tokens/build.ts [--check]   (--check fails if generated files are stale)
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { tokens } from '../../src/tokens/tokens.ts';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '../..');
const outDir = resolve(root, 'src/tokens/generated');

const kebab = (s: string): string => s.replace(/([a-z])([A-Z0-9])/g, '$1-$2').toLowerCase();
const isHex = (v: unknown): v is string => typeof v === 'string' && /^#[0-9A-F]{6}$/i.test(v);

const srgbToLinear = (hex: string): [number, number, number] => {
  const c = [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16) / 255);
  const lin = c.map((x) => (x <= 0.04045 ? x / 12.92 : ((x + 0.055) / 1.055) ** 2.4));
  return lin.map((x) => Math.round(x * 1e6) / 1e6) as [number, number, number];
};

function cssVars(): string[] {
  const t = tokens;
  const lines: string[] = [];
  const add = (name: string, value: string | number): void => {
    lines.push(`  --fx-${name}: ${value};`);
  };
  for (const [k, v] of Object.entries(t.color)) add(`color-${kebab(k)}`, v);
  for (const [k, v] of Object.entries(t.pattern)) add(`pattern-${k}`, v);
  for (const [k, v] of Object.entries(t.world)) add(`3d-${kebab(k)}`, v);
  add('font-micro', t.font.micro);
  add('font-macro', t.font.macro);
  for (const [k, v] of Object.entries(t.type)) {
    const n = `type-${kebab(k)}`;
    add(n, v.size);
    add(`${n}-leading`, v.leading);
    add(`${n}-tracking`, v.tracking);
    add(`${n}-weight`, v.weight);
  }
  t.space.forEach((v, i) => add(`space-${i}`, v));
  for (const [k, v] of Object.entries(t.size)) add(k === 'hudGutter' ? 'hud-gutter' : `size-${kebab(k)}`, v);
  add('radius', t.radius);
  add('shadow', t.shadow);
  for (const [k, v] of Object.entries(t.rule)) add(`rule-${k}`, v);
  add('focus-ring', t.focus.ring);
  add('focus-offset', t.focus.offset);
  for (const [k, v] of Object.entries(t.z)) add(`z-${kebab(k)}`, v);
  for (const [k, v] of Object.entries(t.motion.dur)) add(`dur-${k}`, v);
  for (const [k, v] of Object.entries(t.motion.ease)) add(`ease-${k}`, v);
  return lines;
}

function render(): { css: string; json: string } {
  const header = '/* GENERATED by scripts/tokens/build.ts from src/tokens/tokens.ts — do not edit. */';
  const css = `${header}\n:root {\n${cssVars().join('\n')}\n}\n`;
  const withLinear = (obj: object): unknown =>
    Object.fromEntries(
      Object.entries(obj).map(([k, v]) => [
        k,
        isHex(v)
          ? { srgb: v.toUpperCase(), linear: srgbToLinear(v) }
          : typeof v === 'object' && v !== null
            ? withLinear(v)
            : v,
      ]),
    );
  const { pattern: _pattern, ...rest } = tokens;
  const json = `${JSON.stringify({ $generated: 'scripts/tokens/build.ts', ...(withLinear(rest) as object) }, null, 2)}\n`;
  return { css, json };
}

const files = render();
const targets: [string, string][] = [
  [resolve(outDir, 'tokens.css'), files.css],
  [resolve(outDir, 'tokens.json'), files.json],
];

if (process.argv.includes('--check')) {
  const stale = targets.filter(([p, content]) => {
    try {
      return readFileSync(p, 'utf8') !== content;
    } catch {
      return true;
    }
  });
  if (stale.length > 0) {
    console.error(
      `tokens: stale generated files (run \`npm run tokens\`):\n${stale.map(([p]) => `  ${p}`).join('\n')}`,
    );
    process.exit(1);
  }
  console.log('tokens: generated files up to date');
} else {
  mkdirSync(outDir, { recursive: true });
  for (const [p, content] of targets) writeFileSync(p, content);
  console.log(`tokens: wrote ${targets.length} files to ${outDir}`);
}
